# R103: `mandapa parimita N` gives a block a byte budget. Its own nirmmita may use at most N bytes
# (each rounded up to 16); the one that would pass it stops the program before it gets memory:
# E_PARIMITA, with the block's line, exit 1. Here 1,000,000 x 64 bytes in one 1 MB block.
mukhya() {
    vitti s = 0
    mandapa parimita 1048576 {
        vitti i = 0
        yavat (i < 1000000) {
            vitti b = nirmmita(64)
            b[0] = i
            s = s + b[0]
            i = i + 1
        }
    }
    likha("not reached ", s)
}

# R107: parimana() - the bytes the program's nirmmita and kosh hold right now. A block gives its
# bytes back at its end; a kosh holds its header and capacity (8 bytes a number) for the program's
# life. Every nirmmita is rounded up to 16 bytes. Linux; a Windows program reads 0.
mukhya() {
    likha("start ", parimana(), "\n")
    vitti a = nirmmita(64)
    likha("after nirmmita(64) ", parimana(), "\n")
    mandapa {
        vitti b = nirmmita(1000)
        likha("in a block, nirmmita(1000) ", parimana(), "\n")
    }
    likha("after the block ", parimana(), "\n")
    kosh k[1]
    vitti i = 0
    yavat (i < 1000) {
        kosh_kship(k, i)
        i = i + 1
    }
    likha("a kosh of 1000 ", parimana(), "\n")
}

